package com.osfans.trime.ai

import io.kotest.assertions.throwables.shouldThrowAny
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import java.util.Base64

class AiBundledDefaultsTest :
    FunSpec({
        // Public synthetic vector generated by Python cryptography, not a live key.
        val key = "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="
        val envelope = "AAECAwQFBgcICQoLNHu4b62AtnLubPPu14gNAff781GDD3IXXR6rTsV9hkfXuqgSeN7b/GAQ"
        test("Android importer reads the build generator's authenticated envelope") {
            AiBundledDefaults.decrypt(envelope, key) shouldBe "synthetic-default-test-key"
            AiBundledDefaults.decrypt("", "") shouldBe ""
        }
        test("tampered or wrongly wrapped credentials fail authentication") {
            val bytes = Base64.getDecoder().decode(envelope)
            bytes[bytes.lastIndex] = (bytes.last().toInt() xor 1).toByte()
            shouldThrowAny { AiBundledDefaults.decrypt(Base64.getEncoder().encodeToString(bytes), key) }
            shouldThrowAny { AiBundledDefaults.decrypt(envelope, Base64.getEncoder().encodeToString(ByteArray(32))) }
        }
        test("default credentials stay bound to official HTTPS chat paths") {
            for (endpoint in listOf("https://api.deepseek.com/chat/completions", "https://api.deepseek.com:443/v1/chat/completions")) {
                AiBundledDefaults.isOfficialEndpoint(endpoint) shouldBe true
            }
            for (endpoint in listOf("http://api.deepseek.com/chat/completions", "https://api.deepseek.com.example.com/chat/completions", "https://user@api.deepseek.com/chat/completions", "https://api.deepseek.com:8443/chat/completions", "https://api.deepseek.com/audio/transcriptions", "https://api.deepseek.com/chat/completions?forward=elsewhere", "https://api.deepseek.com/chat/completions#fragment")) {
                AiBundledDefaults.isOfficialEndpoint(endpoint) shouldBe false
            }
        }
    })
